import{_ as a,c as n,o as e,at as i}from"./chunks/framework.mXguc-v6.js";const u=JSON.parse('{"title":"Concurrent Mode 如何工作？","description":"","frontmatter":{},"headers":[],"relativePath":"views/interview/frontend/react/concurrent.md","filePath":"views/interview/frontend/react/concurrent.md","lastUpdated":null}'),t={name:"views/interview/frontend/react/concurrent.md"};function r(p,s,l,o,c,d){return e(),n("div",null,s[0]||(s[0]=[i(`<h1 id="concurrent-mode-如何工作" tabindex="-1">Concurrent Mode 如何工作？ <a class="header-anchor" href="#concurrent-mode-如何工作" aria-label="Permalink to &quot;Concurrent Mode 如何工作？&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>Concurrent Mode 不是让渲染变快，而是让 React <strong>能同时准备多个版本的 UI</strong>，让高优先级更新插队执行。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统模式：</span></span>
<span class="line"><span>  更新 A → 渲染完 A → 更新 B → 渲染完 B</span></span>
<span class="line"><span></span></span>
<span class="line"><span>并发模式：</span></span>
<span class="line"><span>  更新 A 开始 → 紧急的 B 插队 → 暂停 A → 优先 B → 恢复 A</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="时间分片" tabindex="-1">时间分片 <a class="header-anchor" href="#时间分片" aria-label="Permalink to &quot;时间分片&quot;">​</a></h2><p>JS 单线程，React 用 Fiber 把渲染任务切成 5ms 小块模拟并发效果。</p><h2 id="suspense-悬念" tabindex="-1">Suspense（悬念） <a class="header-anchor" href="#suspense-悬念" aria-label="Permalink to &quot;Suspense（悬念）&quot;">​</a></h2><p>声明式加载状态——子组件没准备好时显示 fallback，准备好后无缝切换。</p><div class="language-tsx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Suspense</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fallback</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Loading</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;}&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SomeSlowComponent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Suspense</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>配合 Concurrent Mode：Suspense 组件没准备好时，React 先渲染其他就绪部分，这叫 <strong>流式渲染</strong>。</p><h2 id="三者关系" tabindex="-1">三者关系 <a class="header-anchor" href="#三者关系" aria-label="Permalink to &quot;三者关系&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Fiber（基础设施）</span></span>
<span class="line"><span>  → 时间分片让渲染可中断</span></span>
<span class="line"><span>  → Concurrent Mode 让优先级调度成为可能</span></span>
<span class="line"><span>  → Suspense 利用这个能力实现流式加载</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="面试追问" tabindex="-1">面试追问 <a class="header-anchor" href="#面试追问" aria-label="Permalink to &quot;面试追问&quot;">​</a></h2><p><strong>Q: React 18 的 createRoot 默认就是 Concurrent Mode 吗？</strong><code>createRoot</code> 开启了并发特性，但 Suspense/transitions 需要主动使用才生效。</p>`,14)]))}const b=a(t,[["render",r]]);export{u as __pageData,b as default};
